  // ── Dung Hợp: 30 descs ──
  'Hắc động thôn phệ — hút 40% sát thương thành sinh lực & phản đòn trong 8s.': 'A devouring black hole — convert 40% damage to HP & reflect for 8s.',
  'Thất thương tẫn hại — quyền kính 7 lớp chấn nát địch, choáng & hất văng.': 'Seven layers of ruinous fist force — shatter foes, stun & knock back.',
  'Âm hàn nhập cốt — chưởng lực đông cứng gân cốt, chảy máu & chậm 70%.': 'Yin frost enters the bone — palms freeze sinews, bleed & 70% slow.',
  'Cửu dương tề tựu — nội lực vô biên, +70% sát thương trong 8s.': 'Nine yangs converge — boundless inner force, +70% damage for 8s.',
  'Long tượng hiện hình — mười tầng lực đạo nghiền nát toàn trường.': 'Dragon-elephant manifests — ten tiers of force crush the whole field.',
  'Đao pháp truyền đời — ba đạo đao quang băng hàn xuyên thấu.': 'Ancestral blade art — three arcs of freezing blade light, piercing.',
  'Kim xà phóng độc — kiếm quang như rắn vàng cắn xé, trúng kịch độc.': 'The golden snake strikes — sword light bites like a viper, inflicting deadly poison.',
  'Chiết mai trong hư không — cánh hoa hóa thủ ấn, choáng 2s xuyên giáp.': 'Plucking plum blossoms from thin air — petals turn to hand seals, 2s stun, armor-piercing.',
  'Lục dương luân chuyển — sáu vầng thái dương nổ tung quanh người.': 'Six suns revolve — solar bursts erupt all around you.',
  'Âm ba sưu hồn — bốn đạo tử khí xuyên thấu, đoạt mệnh vô thanh.': 'Soul-reaping sound waves — four piercing bolts of death qi, silent and lethal.',
  'Duy ngã độc tôn — +40% ST & hút 20% sinh lực trong 10s.': 'I alone am supreme — +40% DMG & 20% life steal for 10s.',
  'Miên chưởng hóa cốt — trúng chưởng xương cốt nhũn ra, chảy máu 8s.': "Cotton palm melts bone — struck foes' bones soften, bleeding for 8s.",
  'Chỉ phong huyễn ảnh — một chỉ xuyên thấu ảo ảnh, choáng 1.5s.': 'Phantom finger wind — one piercing strike through illusions, 1.5s stun.',
  'Kim cang bất hoại — khiên 60% HP & +20% ST trong 6s.': 'Vajra unbreakable — 60% HP shield & +20% DMG for 6s.',
  'Đệ nhất thần công — đốn ngộ thái huyền: +100% ST & khiên 30% HP trong 10s.': 'The first divine art — sudden grand-mystic enlightenment: +100% DMG & 30% HP shield for 10s.',
  'Ngự kiếm mà đi — hóa thành kiếm quang xé gió, chém xuyên địch cuối đường.': 'Ride the sword — become wind-rending sword light, slashing through to the last foe.',
  'Vạn kiếm triều tông — chín đạo phi kiếm quét ngang, xuyên thấu tuyệt đối.': 'Ten thousand swords converge — nine flying blades sweep wide, absolute pierce.',
  'Cửu thiên giáng lôi — lôi trụ tử điện đánh xuống, choáng toàn trường.': 'Thunder falls from nine heavens — a violet lightning pillar, field-wide stun.',
  'Phượng hoàng dục hỏa — liệt diễm trùm trời, niết bàn trùng sinh.': 'The phoenix bathes in fire — flames blanket the sky, rebirth from nirvana.',
  'Huyền băng phong ấn — hàn khí đóng băng tứ chi, chậm 80% & choáng.': 'Mystic ice seal — frost freezes limbs, 80% slow & stun.',
  'Độn hình ngũ hành — lướt xa 260px, né tuyệt đối 3s.': 'Vanish through the five elements — dash 260px, absolute dodge for 3s.',
  'Giải thể bộc phát — tốc đánh +80%, mọi đòn bạo kích trong 6s.': 'Disintegration burst — +80% attack speed, every hit crits for 6s.',
  'Huyết ma phệ hồn — trảo huyết xé hồn phách, chảy máu 6s.': 'The blood demon devours souls — crimson claws tear the spirit, 6s bleed.',
  'Thái Ất huyền quang — một kiếm phá vạn pháp, tốc độ cực hạn.': 'Grand Unity mystic light — one sword breaks ten thousand arts, at utmost speed.',
  'Tứ tượng tề giáng — Thanh Long Bạch Hổ Chu Tước Huyền Vũ trấn áp, choáng 1.5s.': 'Four symbols descend — Azure Dragon, White Tiger, Vermilion Bird, Black Tortoise suppress all, 1.5s stun.',
  'Vạn lý giao băng — sóng băng phủ toàn trường, chậm 60% trong 5s.': 'Ten thousand li frozen — ice waves blanket the field, 60% slow for 5s.',
  'Lôi quân vạn mã — sấm sét như thiên binh quét sạch bát phương.': 'Thunder cavalry in legion — lightning like heavenly soldiers sweeps the eight directions.',
  'Thôn thiên phệ địa — hút 35% sinh lực & +30% ST trong 8s.': 'Devour heaven and earth — 35% life steal & +30% DMG for 8s.',
  'Đại la kiếm trận — năm thanh tiên kiếm đồng loạt xuất kích.': 'Grand Luo sword formation — five immortal swords strike as one.',
  'Phật ấn giáng thế — kim chưởng niết bàn trấn áp chư ma.': 'The Buddha seal descends — a golden nirvana palm suppresses all demons.',
  // ── SKILL_DEFS names + descs ──
  'Ám Khí': 'Hidden Weapons',
  'Phóng ám khí độc — theo tầng Tuyệt Học Ám Khí.': 'Hurls poisoned hidden weapons — scales with the Hidden Weapons Ultimate tier.',
  'Đạn Chỉ Thần Thông': 'Divine Finger Flick',
  'Chỉ lực xuyên huyệt — sát thương ×2 và phong mạch địch 2.5s.': "Finger force pierces meridians — ×2 damage and seals the foe's meridians for 2.5s.",
  'Linh Tiễn Xạ': 'Spirit Arrow Shot',
  'Bắn 3 linh tiễn xuyên thấu quạt trước mặt.': 'Fire 3 piercing spirit arrows in a frontal fan.',
  'Ám Nhiên Tiêu Hồn Chưởng': 'Soul-Extinguishing Gloomy Palm',
  'Chưởng lực âm nhu quét sạch quanh người (AoE lớn).': 'Dark, soft palm force sweeps all around you (large AoE).',
  '6s giảm 30% sát thương gánh chịu — tụ cương khí hộ thể.': 'For 6s, -30% damage taken — gather vajra qi around the body.',
  // ── PASSIVE_SKILLS: 6 names + 6 descs ──
  'Cung Tiễn (bị động)': 'Archery (passive)',
  'Đòn đánh thường có tỉ lệ bắn linh tiễn — theo tầng Cung Tiễn.': 'Basic attacks may fire spirit arrows — scales with Archery tier.',
  'Lăng Ba Vi Bộ (J)': 'Rippling Wave Steps (J)',
  'Nhảy 2 lần trên không, lướt né mọi đòn — Đan Điền cảnh 7.': 'Double-jump in midair, gliding past all attacks — Dantian Lv 7.',
  'Đạn Chỉ phong mạch (bị động)': 'Finger-Flick Meridian Seal (passive)',
  '5% đòn đánh phong mạch địch — Đan Điền cảnh 4.': "5% of attacks seal the foe's meridians — Dantian Lv 4.",
  'Thái Cực phản đòn (bị động)': 'Taiji Riposte (passive)',
  'Phản lại một phần sát thương — Đan Điền cảnh 5 / trang bị.': 'Reflect part of the damage — Dantian Lv 5 / gear.',
  'Bất Tử (bị động)': 'Undying (passive)',
  'Chặn 1 đòn chí mạng, hồi 30% HP — Đan Điền cảnh 8.': 'Blocks 1 fatal blow, heals 30% HP — Dantian Lv 8.',
  'Huyết Ma Thôn Phệ': 'Blood Demon Devour',
  'Hút 10% sát thương thành sinh lực + tuyệt chiêu chủ động Huyết Ma Phệ Hồn Chưởng (gán ở bảng K) — bí kíp giang hồ.': 'Convert 10% damage to HP + active ultimate Blood Demon Soul-Devouring Palm (assign in the K panel) — a jianghu secret manual.',
