"Thành chính trung tâm — Chợ Đấu Giá, Lò Bát Quái, Dược Phường, Trà Quán. Khu an toàn: quái không thể vào thành. Ra Cổng Nam để săn quái ngoại ô.":"Central city — Auction Market, Eight-Trigram Furnace, Apothecary, Teahouse. Safe zone: monsters cannot enter. Exit via South Gate to hunt the outskirts.",
"Vùng ngoài thành — sơn tặc lập trại chặn đường, lang sói hoành hành. Không PK, an toàn cho tân thủ rèn luyện.":"Outside the city — bandit camps block the roads, wolves roam. No PK, safe for new adventurers.",
"Xích mích nhỏ lẻ bắt đầu. Quái rớt bí kíp cơ bản & bạc vụn.":"Petty feuds begin here. Mobs drop basic manuals & loose silver.",
"Cổ Mộ Mật Thất":"Ancient Tomb Secret Chamber",
"Bản đồ hẹp, nhiều ngõ ngách. Quái đông, rớt nguyên liệu tiến cấp Tọa Kỵ. Tranh bãi khốc liệt.":"Narrow map with many nooks. Dense mobs, drops Mount-upgrade materials. Fierce competition.",
"Bãi EXP khổng lồ. Cần Cương Khí chống sát thương độc của quái.":"Huge EXP grounds. You need Vajra Qi to resist the poison damage of these mobs.",
"Mông Cổ Đại Doanh":"Mongol War Camp",
"Bản đồ rộng, quái trâu & ST cao. Rớt nguyên liệu tiến cấp Cung Tiễn, Ám Khí.":"Wide map, tanky mobs & high DMG. Drops Bow and Hidden-Weapon upgrade materials.",
"Bãi train end-game. PK không Tội Ác. Quái rớt đồ Hoàng kim, ST chí mạng.":"End-game training grounds. PK without Infamy. Mobs drop gold-tier gear with fatal DMG.",
"Phó bản của Đào Hoa Đảo — 3 đợt quái rồi Boss Hắc Phong Trại Chủ. Farm Tiến Cấp Đan & Huyền Thiết.":"Peach Blossom Island dungeon — 3 waves then Boss Blackwind Stronghold Chief. Farm Advancement Pills & Mystic Iron.",
"Phó bản của Ngoại Ô — Boss Sơn Tặc Đại Đầu Lĩnh trấn giữ. Farm Tiến Cấp Đan & Huyền Thiết.":"Outskirts dungeon — guarded by Boss Bandit Warlord. Farm Advancement Pills & Mystic Iron.",
"Phó bản của Chung Nam Sơn — Boss Phản Đồ Đại Tướng. Farm Tiến Cấp Đan, Huyền Thiết & Tu La.":"Mt. Zhongnan dungeon — Boss Renegade General. Farm Advancement Pills, Mystic Iron & Asura gems.",
"Phó bản của Cổ Mộ — Boss Cổ Mộ Mộ Chủ. Farm nguyên liệu tiến cấp Tọa Kỵ & Tuyệt Học.":"Ancient Tomb dungeon — Boss Tomb Keeper. Farm Mount & Ultimate-Arts upgrade materials.",
"Phó bản của Tuyệt Tình Cốc — Boss Tình Hỏa Ma Quân (đòn độc). Farm Tu La & Hỗn Nguyên.":"Heartbreak Valley dungeon — Boss Lovefire Demon Lord (venom strikes). Farm Asura & Chaos gems.",
"Phó bản của Mông Cổ Đại Doanh — Boss Đột Thông Hãn Vương. Farm nguyên liệu tiến cấp Cung Tiễn, Ám Khí.":"Mongol War Camp dungeon — Boss Great Khan Dotong. Farm Bow and Hidden-Weapon upgrade materials.",
"Phó bản của Nhạn Môn Quan — Boss Thiên Binh Thống Soái. Thử thách cuối cùng, thưởng cực hậu.":"Yanmen Pass dungeon — Boss Heavenborn Marshal. The final trial, with lavish rewards.",
