"\"Mộ này… có thứ không nên bị đánh thức. Ngươi nghe thấy gì không?\"":"\"Something in this tomb should never be woken. Do you hear it?\"",
"\"Một lệnh một duyên — năm phần trăm gặp bí kíp hiếm, không gom đủ cũng chẳng thành.\"":"\"One token, one fate — a 5% chance at a rare tome; without enough tokens, it comes to nothing.\"",
"\"Nhai này đoạn trường tình — dưới vực sâu, kẻ hữu duyên sẽ đổi đời.\"":"\"This cliff severs love and grief — in the abyss below, the fated find a new life.\"",
"\"Nếu có kiếp sau, ta không làm Cốc Chủ, nàng đừng làm đệ tử…\"":"\"If there is a next life, I won't be the Valley Master, and she won't be my disciple…\"",
"\"Suỵt… ta là người của Quách Đại Hiệp cắm trong doanh địch đã ba năm.\"":"\"Shh… I'm Guo the Great Hero's plant inside the enemy camp — three years now.\"",
"\"Sư môn phụ bạc ta… nhưng trấn ấn này, ta gánh đến cùng.\" — nét chữ run rẩy.":"\"My sect betrayed me… but this seal, I will bear to the end.\" — the handwriting trembles.",
"\"Ta giữ Nhạn Môn ba mươi năm. Hôm nay ta mở cửa — không phải vì hàng, mà vì hết cách.\"":"\"I held Yanmen Pass for thirty years. Today I open the gate — not from surrender, but from having no way left.\"",
"\"Thuốc hay cứu người — nhưng không trả tiền thì thuốc cũng hóa độc đấy.\"":"\"Good medicine saves lives — but unpaid, even medicine turns to poison.\"",
"\"Thuốc hay cứu người, thuốc độc cũng cứu người — tùy ai dùng.\"":"\"Medicine saves people; poison saves people too — depends on who uses it.\"",
"\"Triều đình treo thưởng tà đạo — mỗi ngày một tên. Làm xong, đến Vạn Duyên Các thử vận.\"":"\"The court posts bounties on heretics — one a day. Finish it, then try your luck at the Myriad Fates Pavilion.\"",
"\"Tuấn mã hoang ngoài đồng kia đấy — rượt cho nó kiệt sức rồi bấm E mà bắt. Mã Thầu thu được dùng khi thăng giai thú cưỡi!\"":"\"Wild stallions out in the fields — chase them until they're spent, then press E to catch one. The Lassos you get are used to rank up your mount!\"",
"\"Vào cốc này rồi, chữ Tình hãy để ngoài cửa.\"":"\"Once inside this valley, leave the word Love at the gate.\"",
"\"Vách mây ngàn trượng — người cầu đạo nhảy xuống, kẻ sợ chết quay đầu.\"":"\"A thousand-yard cloud cliff — those who seek the Dao leap; those who fear death turn back.\"",
"\"Đạo pháp tự nhiên — nhưng phản đồ thì không thể dung tha.\"":"\"The Dao follows nature — but traitors cannot be forgiven.\"",
"\"Động phủ của đạo hữu đã dọn sạch — Tụ Linh Trận và Dược Viên chờ chủ nhân.\"":"\"Your cave abode is ready, fellow Daoist — the Spirit-Gathering Array and Herb Garden await their master.\"",
"\"…khi đủ năm ấn vỡ, Vạn Ma Điện mở — Ma Tôn giáng thế, giang hồ thành lò luyện.\"":"\"…when all five seals break, the Myriad Demon Palace opens — the Demon Lord descends, and the jianghu becomes a furnace.\"",
"\"…năm ấn trấn Ma Tôn tại Tịch Ma Điện. Một ấn vỡ, bốn ấn lung lay…\"":"\"…five seals bind the Demon Lord in the Silent Demon Palace. One seal broken, four more wavering…\"",
